// Prepare Email Data — only extract email metadata + body text for AI.
// Does NOT extract org_name / inn / org_address.

function stripPrefix(s = '', prefix = '') {
  s = String(s || '').trim();
  if (!prefix) return s;
  const re = new RegExp(`^${prefix}\\s*:\\s*`, 'i');
  return s.replace(re, '').trim();
}

function cleanHtml(s = '') {
  return String(s || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>|<\/div>|<\/tr>|<\/li>/gi, '\n')
    .replace(/<\/td>|<\/th>/gi, '\t')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\r/g, '')
    .trim();
}

function extractEmail(s = '') {
  s = String(s || '');
  const m = s.match(/<([^>]+)>/);
  if (m) return m[1].trim();
  const m2 = s.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return m2 ? m2[0].trim() : s.trim();
}

function normalizeSpaces(s = '') {
  return String(s)
    .replace(/\u00A0/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function toMoscowString(dateValue) {
  if (!dateValue) return '';
  try {
    const dt = DateTime.fromJSDate(new Date(dateValue), { zone: 'utc' });
    if (!dt.isValid) {
      const d = new Date(dateValue);
      if (Number.isNaN(d.getTime())) return String(dateValue).trim();
      return d.toISOString();
    }
    return dt.setZone('Europe/Moscow').toFormat('yyyy-LL-dd HH:mm:ss');
  } catch (e) {
    const d = new Date(dateValue);
    if (Number.isNaN(d.getTime())) return String(dateValue || '').trim();
    return d.toISOString();
  }
}

const items = $input.all();

return items.map((item) => {
  const msg = item.json || {};
  const headers = msg.headers || {};

  const sender_email =
    msg.from?.value?.[0]?.address
      ? String(msg.from.value[0].address).trim()
      : extractEmail(stripPrefix(headers.from || msg.from?.text || '', 'From'));

  const subject =
    (msg.subject && String(msg.subject).trim()) ||
    stripPrefix(headers.subject || '', 'Subject') ||
    '';

  const messageDateRaw =
    (msg.date && String(msg.date).trim()) ||
    stripPrefix(headers.date || '', 'Date') ||
    '';

  const message_date = toMoscowString(messageDateRaw);

  const message_id =
    msg.id ||
    msg.messageId ||
    stripPrefix(headers['message-id'] || '', 'Message-Id') ||
    '';
  const thread_id = msg.threadId || '';

  const bodyTextRaw =
    (msg.text && String(msg.text).trim()) ||
    cleanHtml(msg.html || msg.textAsHtml || '');

  const body_full = normalizeSpaces(bodyTextRaw);

  return {
    json: {
      sender_email,
      subject,
      message_date,
      message_id,
      thread_id,
      body_full,
    },
  };
});

