// Validate Organizations — normalize/validate only.
// Returns ONE item with organizations[] (each org already includes email metadata).
// Actual fan-out to multiple n8n items is done by Split Out node.

function normalizeInn(value = '') {
  return String(value ?? '').replace(/\D+/g, '').trim();
}

function tryParseJson(value) {
  if (typeof value !== 'string') return value;
  const s = value.trim();
  if (!s) return value;
  try {
    return JSON.parse(s);
  } catch (e) {
    return value;
  }
}

function asArray(value) {
  value = tryParseJson(value);
  if (Array.isArray(value)) return value;
  if (value && typeof value === 'object') return [value];
  return null;
}

function unwrapExtracted(aiJson) {
  if (!aiJson || typeof aiJson !== 'object') return {};
  if (aiJson.error) return { error: aiJson.error };

  let root = aiJson;
  // Information Extractor: { output: { organizations, warnings } }
  if (root.output !== undefined) root = tryParseJson(root.output);
  // Rare: double wrap
  if (root && typeof root === 'object' && root.output !== undefined && root.organizations === undefined) {
    root = tryParseJson(root.output);
  }
  // Rare: output is directly the organizations array
  if (Array.isArray(root)) {
    return { organizations: root, warnings: [] };
  }
  if (!root || typeof root !== 'object') return {};
  return root;
}

const prepareItems = $items('Prepare Email Data');
const aiItems = $input.all();
const output = [];

for (let i = 0; i < aiItems.length; i++) {
  const aiJson = aiItems[i].json || {};
  const meta = (prepareItems[i] || prepareItems[0] || { json: {} }).json || {};

  const emailMeta = {
    sender_email: meta.sender_email || '',
    subject: meta.subject || '',
    message_date: meta.message_date || '',
    message_id: meta.message_id || '',
    thread_id: meta.thread_id || '',
    body_full: meta.body_full || '',
  };

  const extracted = unwrapExtracted(aiJson);

  if (extracted.error) {
    output.push({
      json: {
        ...emailMeta,
        organizations: [],
        warnings: [],
        error_reason: String(extracted.error),
        needs_manual_review: true,
      },
    });
    continue;
  }

  const warningsRaw = asArray(extracted.warnings);
  const warnings = warningsRaw ? warningsRaw.map(String) : [];
  const organizations = asArray(extracted.organizations);

  if (!organizations) {
    output.push({
      json: {
        ...emailMeta,
        organizations: [],
        warnings,
        error_reason: 'Invalid AI structure: organizations is not an array',
        needs_manual_review: true,
      },
    });
    continue;
  }

  const localWarnings = [...warnings];
  const validOrgs = [];
  const seenInns = new Set();

  for (const org of organizations) {
    const row = org && typeof org === 'object' ? org : {};
    const org_name = String(row.org_name ?? '').trim();
    const org_address = String(row.org_address ?? '').trim();
    const inn = normalizeInn(row.inn);

    if (!inn || (inn.length !== 10 && inn.length !== 12)) {
      localWarnings.push(
        `Excluded "${org_name || 'unknown'}": INN must be 10 or 12 digits (got "${row.inn ?? ''}")`
      );
      continue;
    }

    if (!org_name) {
      localWarnings.push(`Excluded INN ${inn}: empty org_name`);
      continue;
    }

    if (seenInns.has(inn)) {
      localWarnings.push(`Skipped duplicate INN within same email: ${inn} (${org_name})`);
      continue;
    }
    seenInns.add(inn);

    // Metadata duplicated into each org so Split Out (noOtherFields) keeps flat items
    validOrgs.push({
      ...emailMeta,
      org_name,
      inn,
      org_address,
      needs_manual_review: false,
    });
  }

  if (validOrgs.length === 0) {
    output.push({
      json: {
        ...emailMeta,
        organizations: [],
        warnings: localWarnings,
        error_reason: localWarnings.length
          ? localWarnings.join('; ')
          : 'No valid organizations extracted',
        needs_manual_review: true,
      },
    });
    continue;
  }

  output.push({
    json: {
      ...emailMeta,
      organizations: validOrgs,
      warnings: localWarnings,
      needs_manual_review: false,
      org_count: validOrgs.length,
    },
  });
}

return output;

// Needs Manual Review — package payload for human review.
// No Sheets write, no auto-reply.
const items = $input.all();

return items.map((item) => {
  const j = item.json || {};
  return {
    json: {
      review_status: 'needs_manual_review',
      sender_email: j.sender_email || '',
      subject: j.subject || '',
      message_id: j.message_id || '',
      thread_id: j.thread_id || '',
      message_date: j.message_date || '',
      body_full: j.body_full || '',
      warnings: Array.isArray(j.warnings) ? j.warnings : [],
      error_reason: j.error_reason || 'Recognition failed or no valid organizations',
      organizations: Array.isArray(j.organizations) ? j.organizations : [],
    },
  };
});

// Check each organization INN independently against Google Sheets lookup results.
function normalizeInn(value = '') {
  return String(value ?? '').replace(/\D+/g, '').trim();
}

const orgItems = $items('Split Organizations')
  .map((i) => i.json || {})
  .filter((j) => j && j.inn && !j.needs_manual_review);

const sheetItems = $input.all();
const rows = sheetItems.map((i) => i.json || {});

const innKeys = ['inn', 'ИНН', 'Inn', 'INN'];
function getRowInn(row) {
  for (const k of innKeys) {
    if (row[k] !== undefined && row[k] !== null && String(row[k]).trim() !== '') {
      return normalizeInn(row[k]);
    }
  }
  return '';
}

// Pair each org with its own Sheets lookup result(s) via pairedItem when possible.
function pairedIndex(item, fallback) {
  const pi = item.pairedItem;
  if (typeof pi === 'number') return pi;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') return pi.item;
  if (Array.isArray(pi) && pi[0] && typeof pi[0].item === 'number') return pi[0].item;
  return fallback;
}

const rowsByOrgIndex = new Map();
sheetItems.forEach((item, idx) => {
  const orgIdx = pairedIndex(item, idx);
  if (!rowsByOrgIndex.has(orgIdx)) rowsByOrgIndex.set(orgIdx, []);
  rowsByOrgIndex.get(orgIdx).push(item.json || {});
});

return orgItems.map((p, idx) => {
  const inn = normalizeInn(p.inn || '');
  const matchedRows = rowsByOrgIndex.get(idx) || [];
  const matchedInns = matchedRows.map(getRowInn).filter(Boolean);
  // Fallback: also check aggregated set (covers alwaysOutputData empty objects)
  const exists = Boolean(inn) && (
    matchedInns.includes(inn) ||
    rows.some((r) => getRowInn(r) === inn)
  );

  return {
    json: {
      sender_email: p.sender_email || '',
      subject: p.subject || '',
      message_date: p.message_date || '',
      message_id: p.message_id || '',
      thread_id: p.thread_id || '',
      body_full: p.body_full || '',
      org_name: p.org_name || '',
      org_address: p.org_address || '',
      inn,
      inn_exists: exists,
      needs_manual_review: false,
      rows_count: matchedRows.length,
    },
  };
});
